<?php require_once dirname(__DIR__).'/includes/auth.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT a.*,u.name,u.email,q.title FROM attempts a JOIN users u ON u.id=a.user_id JOIN quizzes q ON q.id=a.quiz_id WHERE a.id=?');$s->execute([$id]);$a=$s->fetch()?:exit('Resposta não encontrada.');$s=db()->prepare('SELECT q.question_text,q.type,q.points,ans.text_answer,ans.is_correct,ans.points_awarded,o.option_text FROM answers ans JOIN questions q ON q.id=ans.question_id LEFT JOIN question_options o ON o.id=ans.selected_option_id WHERE ans.attempt_id=? ORDER BY q.position');$s->execute([$id]);$answers=$s->fetchAll();$pageTitle='Respostas de '.$a['name'];require dirname(__DIR__).'/includes/header.php'; ?>
<section class="admin-head compact"><div><a class="back" href="<?= e(url('admin/quiz_results.php?id='.$a['quiz_id'])) ?>">← Voltar</a><div class="eyebrow">RESPOSTA INDIVIDUAL</div><h1><?= e($a['name']) ?></h1><p><?= e($a['email']) ?> · <?= e($a['title']) ?></p></div><div class="grade"><strong><?= e($a['score']) ?>/<?= e($a['max_score']) ?></strong><span>pontos</span></div></section><div class="answers-list"><?php foreach($answers as $i=>$ans): ?><article><div class="answer-head"><span><?= $i+1 ?></span><h2><?= e($ans['question_text']) ?></h2><?php if($ans['is_correct']!==null): ?><b class="<?= $ans['is_correct']?'correct':'wrong' ?>"><?= $ans['is_correct']?'Correta':'Incorreta' ?></b><?php else: ?><b class="open">Aberta</b><?php endif; ?></div><div class="given-answer"><small>RESPOSTA DO COLABORADOR</small><p><?= e($ans['type']==='text'?$ans['text_answer']:$ans['option_text']) ?></p></div></article><?php endforeach; ?></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>

